g=[[0]*21 for _ in range(21)]
pts={3:[(0,14),(3,17),(5,9),(6,10),(6,13),(8,15),(8,17)],4:[(3,2)],6:[(2,3),(17,3)],7:[(2,6)],1:[(2,7),(17,7)],8:[(13,10),(15,16),(17,13)]}
for col,ps in pts.items():
 for r,c in ps:g[r][c]=col
# draw 3 aligned pair connections
p=pts[3]
for i,(r1,c1) in enumerate(p):
 for r2,c2 in p[i+1:]:
  if r1==r2 or c1==c2 or abs(r1-r2)==abs(c1-c2):
   dr=0 if r1==r2 else (1 if r2>r1 else -1)
   dc=0 if c1==c2 else (1 if c2>c1 else -1)
   n=max(abs(r2-r1),abs(c2-c1))
   for t in range(n+1):g[r1+dr*t][c1+dc*t]=3
# lines for 1 and 6
for col,(a,b) in [(6,pts[6]),(1,pts[1])]:
 r1,c1=a;r2,c2=b
 for t in range(max(abs(r2-r1),abs(c2-c1))+1):
  g[r1+(0 if r1==r2 else (1 if r2>r1 else -1))*t][c1+(0 if c1==c2 else (1 if c2>c1 else -1))*t]=col
# extend color 4 alongside vertical 6 boundary
for r in range(3,18):g[r][2]=4
import json
print(json.dumps(g,separators=(',',':')))

